# Decode cipher hex from export - let's try XOR with simple keys
python3 << 'PYEOF'
import binascii
cipher_hex = "0553c2c82d59b219c82e3443a017da2c42952a2c425d53921de4861f4d054be8757cb6eb6714"
cipher = binascii.unhexlify(cipher_hex)
print(f"Cipher len: {len(cipher)} bytes")
# Try single-byte XOR decode
for key in range(256):
    plain = bytes([b ^ key for b in cipher])
    try:
        text = plain.decode('ascii')
        if 'FLAG' in text or 'flag' in text.lower() or 'admin' in text.lower() or 'token' in text.lower():
            print(f"Key {key}: {text}")
    except:
        pass
# Try repeating XOR with common keys
for k in [b'key', b'secret', b'password', b'staff789', b'admin', b'shopadmin']:
    plain = bytes([cipher[i] ^ k[i % len(k)] for i in range(len(cipher))])
    try:
        text = plain.decode('ascii')
        if all(32 <= ord(c) < 127 for c in text):
            print(f"Key '{k.decode()}': {text}")
    except:
        pass
PYEOF

